+  \colorbox{accent!22!bg}{\parbox{0.95\linewidth}{\fontsize{30}{38}\selectfont\color{text}\textbf{Quantified example:} Layer 5 recurrent:feedforward = \textbf{4.7:1}.}}
+  \vspace{2mm}
+  \colorbox{gold!20!bg}{\parbox{0.95\linewidth}{\fontsize{30}{38}\selectfont\color{text}\textbf{Interpretation:} finite motif set \;$\to$\; compositional circuit design.}}
+  }
+}
