+  {\fontsize{30}{40}\selectfont\color{textmuted}
+  Nature (2024). \textit{Mapping neural circuit architecture: advances in brain connectivity analysis}.\\
+  DOI: \texttt{10.1038/s41586-024-07487-w}
+  }\\[5mm]
+  {\fontsize{30}{40}\selectfont\color{textmuted}
+  Poster generated for a neuroscience symposium audience.
+  }
+}
