+    \node[node] (a) at (0,0) {\fontsize{28}{34}\selectfont\textbf{Imaging}\\\fontsize{24}{30}\selectfont serial EM\\4\,nm\,$\times$\,4\,nm\,$\times$\,30\,nm};
+    \node[node] (b) at (0,-25) {\fontsize{28}{34}\selectfont\textbf{Reconstruction}\\\fontsize{24}{30}\selectfont deep segmentation\\+ proofreading};
+    \node[node] (c) at (0,-50) {\fontsize{28}{34}\selectfont\textbf{Synapses}\\\fontsize{24}{30}\selectfont CNN detector\\94.2\% acc.};
+    \node[node] (d) at (0,-75) {\fontsize{28}{34}\selectfont\textbf{Analysis}\\\fontsize{24}{30}\selectfont graph motifs\\+ clustering};
+    \draw[arr] (a) -- (b);
+    \draw[arr] (b) -- (c);
+    \draw[arr] (c) -- (d);
+  \end{tikzpicture}
+  \end{center}
+  \vspace{1mm}
+  \colorbox{teal!22!bg}{\parbox{0.95\linewidth}{\fontsize{30}{38}\selectfont\color{text}\textbf{Validation:} calcium imaging + optogenetic perturbations.}}
+  }
+}
+
+\posterbox[highlightcard]{name=findings, column=3, between=row6 and row11}{%
+  {\fontsize{34}{44}\selectfont\color{text}
+  \textbf{Key Findings (most important)}}\\[3mm]
+  \begin{itemize}
+    \item \textbf{37 motifs} form a modular wiring vocabulary
+    \item \textbf{Hub neurons:} 3.5\% \;$\Rightarrow$\; 28\% synaptic output
+    \item \textbf{Layer rules:} L2/3$\to$L4 feedforward; L5 recurrent enriched
+    \item \textbf{Cell-type specificity:} inhibition 6.2$\times$ more specific
+  \end{itemize}
+  \vspace{2mm}
+  \colorbox{accent!22!bg}{\parbox{0.95\linewidth}{\fontsize{30}{38}\selectfont\color{text}\textbf{Quantified example:} Layer 5 recurrent:feedforward = \textbf{4.7:1}.}}
+  \vspace{2mm}
+  \colorbox{gold!20!bg}{\parbox{0.95\linewidth}{\fontsize{30}{38}\selectfont\color{text}\textbf{Interpretation:} finite motif set \;$\to$\; compositional circuit design.}}
+  }
+}
+
