+    {\fontsize{30}{38}\selectfont\color{textmuted}Connectivity motifs} & {\fontsize{34}{42}\selectfont\bfseries\color{text}37 distinct types}\\
+    {\fontsize{30}{38}\selectfont\color{textmuted}Hub neuron fraction} & {\fontsize{34}{42}\selectfont\bfseries\color{text}3.5\% \;$\to$\; 28\% output}\\
+    {\fontsize{30}{38}\selectfont\color{textmuted}Layer 5 recurrence} & {\fontsize{34}{42}\selectfont\bfseries\color{text}4.7:1 recurrent/feedforward}\\
+    {\fontsize{30}{38}\selectfont\color{textmuted}Inhibitory specificity} & {\fontsize{34}{42}\selectfont\bfseries\color{text}6.2$\times$ vs excitatory}\\
+    {\fontsize{30}{38}\selectfont\color{textmuted}Dataset scale} & {\fontsize{34}{42}\selectfont\bfseries\color{text}~125k neurons; ~54M synapses}\\
+  \end{tabular}
+  \vspace{2mm}
+  \colorbox{accent!20!bg}{\parbox{0.95\linewidth}{\fontsize{30}{38}\selectfont\color{text}\textbf{Automation milestone:} near-human neuron-type labeling at scale.}}
+  }
+}
+
+\posterbox[goldcard]{name=motifs, column=2, between=row11 and row16}{%
+  {\fontsize{34}{44}\selectfont\color{text}
