+\posterbox[goldcard]{name=takeaways, column=2, between=row16 and bottom}{%
+  {\fontsize{34}{44}\selectfont\color{text}
+  \textbf{Take-Home Messages}}\\[2mm]
+  \begin{itemize}
+    \item Scale enables new, testable circuit laws
+    \item Motifs provide modular building blocks
+    \item Automation makes connectomics practical
+  \end{itemize}
+  \vspace{2mm}
+  \colorbox{accent!22!bg}{\parbox{0.95\linewidth}{\fontsize{30}{38}\selectfont\color{text}\textbf{Bottom line:} synapse-resolved maps \;$\to$\; mechanistic circuit science.}}
+  }
+}
+
+\posterbox[tealcard]{name=notes, column=3, between=row16 and bottom}{%
+  {\fontsize{34}{44}\selectfont\color{text}
+  \textbf{Notes on the Dataset}}\\[2mm]
+  \begin{itemize}
+    \item Serial-section EM at \textbf{4\,nm}\,$\times$\,\textbf{4\,nm}\,$\times$\,\textbf{30\,nm}
+    \item Automated synapse detection at \textbf{94.2\%}
+    \item Graph motif discovery reveals \textbf{37} building blocks
